-- HEXA PLUS relational foundation. No business/demo facts are inserted.
begin;
create extension if not exists pgcrypto;
create table public.roles(id uuid primary key default gen_random_uuid(),name text not null unique,description text,created_at timestamptz not null default now());
create table public.permissions(id uuid primary key default gen_random_uuid(),name text not null unique,description text);
create table public.role_permissions(id uuid primary key default gen_random_uuid(),role_id uuid not null references public.roles(id) on delete cascade,permission_id uuid not null references public.permissions(id) on delete cascade,unique(role_id,permission_id),created_at timestamptz not null default now());
create table public.departments(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,email text not null,phone text,job_title text,avatar_path text,department_id uuid references public.departments(id) on delete set null,joining_date date, status text not null default 'active' check(status in ('active','inactive')),role_id uuid references public.roles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null);
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=auth.uid() and p.status='active' and r.name='super_admin')$$;
create or replace function public.has_permission(requested text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id left join public.role_permissions rp on rp.role_id=r.id left join public.permissions pe on pe.id=rp.permission_id where p.id=auth.uid() and p.status='active' and (r.name='super_admin' or pe.name=requested))$$;
revoke all on function public.has_permission(text),public.is_super_admin() from public;
grant execute on function public.has_permission(text),public.is_super_admin() to authenticated;
create table public.clients(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,company text,email text,phone text,industry text,status text not null default 'prospect' check(status in ('prospect','active','inactive','archived')),account_manager_id uuid references public.profiles(id) on delete set null,notes text);
create table public.leads(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,company text,email text,phone text,source text,service text,budget text,timeline text,description text,stage text not null default 'new' check(stage in ('new','contacted','qualified','proposal_sent','negotiation','won','lost')),expected_value_minor bigint not null default 0 check(expected_value_minor >= 0),assigned_to uuid references public.profiles(id) on delete set null,follow_up_date date,notes text);
create table public.projects(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,client_id uuid references public.clients(id) on delete set null,description text,category text,start_date date,deadline date,budget_minor bigint not null default 0 check(budget_minor >= 0),manager_id uuid references public.profiles(id) on delete set null,status text not null default 'planning' check(status in ('planning','in_progress','review','on_hold','completed','cancelled')),priority text default 'low' check(priority in ('low','normal','high','urgent')),progress bigint not null default 0 check(progress >= 0 and progress <= 100),notes text);
create table public.project_milestones(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,project_id uuid references public.projects(id) on delete set null,deadline date,status text not null default 'planned' check(status in ('planned','in_progress','completed')),notes text);
create table public.tasks(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,title text not null,description text,project_id uuid references public.projects(id) on delete set null,client_id uuid references public.clients(id) on delete set null,assigned_to uuid references public.profiles(id) on delete set null,deadline date,priority text default 'low' check(priority in ('low','normal','high','urgent')),status text not null default 'to_do' check(status in ('to_do','in_progress','in_review','completed')));
create table public.task_comments(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,task_id uuid references public.tasks(id) on delete restrict not null,body text not null);
create table public.project_members(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,project_id uuid references public.projects(id) on delete restrict not null,profile_id uuid references public.profiles(id) on delete restrict not null,unique(project_id,profile_id));
create table public.services(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,name_ar text,slug text not null,division text not null default 'digital' check(division in ('digital','marketing')),description text not null,benefits text,deliverables text,workflow text,pricing text,show_pricing boolean not null default false,image_url text,featured boolean not null default false,published boolean not null default false,sort_order bigint not null default 0 check(sort_order >= 0),unique(slug));
create table public.portfolio_projects(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,title text not null,slug text not null,client_name text,client_id uuid references public.clients(id) on delete set null,category text,industry text,description text,challenge text,solution text,services_provided text,technologies text,results text,project_date date,thumbnail_url text,video_url text,featured boolean not null default false,published boolean not null default false,sort_order bigint not null default 0 check(sort_order >= 0),unique(slug));
create table public.portfolio_media(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,portfolio_project_id uuid references public.portfolio_projects(id) on delete restrict not null,url text not null,alt text not null,sort_order bigint not null default 0 check(sort_order >= 0));
create table public.content_posts(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,title text not null,client_id uuid references public.clients(id) on delete set null,platform text default 'facebook' check(platform in ('facebook','instagram','linkedin','tiktok','youtube','website','other')),content_type text default 'post' check(content_type in ('post','reel','story','article','video','other')),publishing_date date,caption text,hashtags text,designer_id uuid references public.profiles(id) on delete set null,copywriter_id uuid references public.profiles(id) on delete set null,editor_id uuid references public.profiles(id) on delete set null,status text not null default 'idea' check(status in ('idea','draft','in_production','review','scheduled','published')));
create table public.marketing_campaigns(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,client_id uuid references public.clients(id) on delete set null,platform text,objective text,start_date date,end_date date,budget_minor bigint not null default 0 check(budget_minor >= 0),ad_spend_minor bigint not null default 0 check(ad_spend_minor >= 0),target_audience text,status text not null default 'planned' check(status in ('planned','active','paused','completed')),leads_generated bigint not null default 0 check(leads_generated >= 0),engagement bigint not null default 0 check(engagement >= 0),reach bigint not null default 0 check(reach >= 0),conversions bigint not null default 0 check(conversions >= 0),results text,notes text);
create table public.social_accounts(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,platform text not null,url text not null,client_id uuid references public.clients(id) on delete set null,notes text);
create table public.invoices(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,invoice_number text not null,client_id uuid references public.clients(id) on delete restrict not null,project_id uuid references public.projects(id) on delete set null,issue_date date not null,due_date date not null,tax_bps bigint not null default 0 check(tax_bps >= 0),notes text,subtotal_minor bigint not null default 0 check(subtotal_minor>=0),tax_minor bigint not null default 0 check(tax_minor>=0),total_minor bigint not null default 0 check(total_minor>=0),unique(invoice_number));
create table public.payments(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,invoice_id uuid references public.invoices(id) on delete restrict not null,amount_minor bigint not null default 0 check(amount_minor >= 0),paid_at date not null,method text default 'bank_transfer' check(method in ('bank_transfer','cash','wallet','card','other')),reference text,notes text);
create table public.expenses(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,project_id uuid references public.projects(id) on delete set null,amount_minor bigint not null default 0 check(amount_minor >= 0),category text,expense_date date not null,notes text);
create table public.files(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,folder text,client_id uuid references public.clients(id) on delete set null,project_id uuid references public.projects(id) on delete set null,storage_path text not null unique,mime_type text not null,size_bytes bigint not null check(size_bytes>=0));
create table public.notifications(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,title text,body text,read_at text,recipient_id uuid references public.profiles(id) on delete cascade,link text);
create table public.activity_logs(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,action text,entity_table text,entity_id text,actor_id uuid references public.profiles(id) on delete set null,changes jsonb not null default '{}'::jsonb);
create table public.lead_activities(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,lead_id uuid references public.leads(id) on delete restrict not null,body text not null,kind text default 'note' check(kind in ('note','call','email','meeting','follow_up')));
create table public.website_settings(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,key text not null,value text not null,is_public boolean not null default false,unique(key));
create table public.testimonials(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,name text not null,company text,quote text not null,published boolean not null default false);
create table public.invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,description text not null,quantity integer not null check(quantity between 1 and 100000),unit_price_minor bigint not null check(unit_price_minor between 0 and 100000000),sort_order integer not null default 0);
create table public.task_attachments(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,file_id uuid not null references public.files(id) on delete cascade,created_at timestamptz not null default now(),unique(task_id,file_id));
create table public.contact_submissions(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id) on delete cascade,consent boolean not null default true,created_at timestamptz not null default now());
create or replace function public.stamp_record() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if TG_OP='INSERT' then NEW.created_by=auth.uid();end if;NEW.updated_at=now();NEW.updated_by=auth.uid();return NEW;end;$$;
create or replace function public.log_change() returns trigger language plpgsql security definer set search_path='' as $$ begin
 insert into public.activity_logs(action,entity_table,entity_id,actor_id,changes) values(lower(TG_OP),TG_TABLE_NAME,coalesce(NEW.id,OLD.id)::text,auth.uid(),jsonb_build_object('record',coalesce(NEW.id,OLD.id)));
 return coalesce(NEW,OLD);end;$$;
alter table public.clients enable row level security;
create trigger stamp before insert or update on public.clients for each row execute function public.stamp_record();
create trigger audit after insert or update or delete on public.clients for each row execute function public.log_change();
create index if not exists clients_created_idx on public.clients(created_at desc);
