create policy authenticated_read on public.roles for select to authenticated using(true);
create policy super_manage on public.roles for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create policy authenticated_read on public.permissions for select to authenticated using(true);
create policy super_manage on public.permissions for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create policy role_permissions_read on public.role_permissions for select to authenticated using(public.is_super_admin() or role_id=(select role_id from public.profiles where id=auth.uid()));
create policy super_manage on public.role_permissions for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create policy module_read on public.clients for select to authenticated using(public.has_permission('clients.read'));
create policy module_insert on public.clients for insert to authenticated with check(public.has_permission('clients.write'));
create policy module_update on public.clients for update to authenticated using(public.has_permission('clients.write')) with check(public.has_permission('clients.write'));
create policy module_delete on public.clients for delete to authenticated using(public.has_permission('clients.write'));
create policy module_read on public.leads for select to authenticated using(public.has_permission('leads.read'));
create policy module_insert on public.leads for insert to authenticated with check(public.has_permission('leads.write'));
create policy module_update on public.leads for update to authenticated using(public.has_permission('leads.write')) with check(public.has_permission('leads.write'));
create policy module_delete on public.leads for delete to authenticated using(public.has_permission('leads.write'));
create policy module_read on public.projects for select to authenticated using((public.has_permission('projects.read') and (manager_id=auth.uid() or public.has_permission('projects.write') or exists(select 1 from public.project_members pm where pm.project_id=projects.id and pm.profile_id=auth.uid()))));
create policy module_insert on public.projects for insert to authenticated with check(public.has_permission('projects.write'));
create policy module_update on public.projects for update to authenticated using(public.has_permission('projects.write')) with check(public.has_permission('projects.write'));
create policy module_delete on public.projects for delete to authenticated using(public.has_permission('projects.write'));
create policy module_read on public.project_milestones for select to authenticated using(public.has_permission('projects.read'));
create policy module_insert on public.project_milestones for insert to authenticated with check(public.has_permission('projects.write'));
create policy module_update on public.project_milestones for update to authenticated using(public.has_permission('projects.write')) with check(public.has_permission('projects.write'));
create policy module_delete on public.project_milestones for delete to authenticated using(public.has_permission('projects.write'));
create policy module_read on public.tasks for select to authenticated using((public.has_permission('tasks.read') and (assigned_to=auth.uid() or public.has_permission('tasks.write'))));
create policy module_insert on public.tasks for insert to authenticated with check(public.has_permission('tasks.write'));
